INSERT INTO npc_text_templates (npc_key, scene_key, display_name, description)
VALUES
    ('Agate_001', 'Agate', '', 'Want to return to Athens?'),
    ('Agate_002', 'Agate', 'Athens Transporter', 'Want to return to Athens?'),
    ('Agate_003', 'Agate', 'Athens Transporter', 'Want to return to Athens?'),
    ('Agate_004', 'Agate', 'Sparta Transporter', 'Want to return to Sparta?'),
    ('Agate_005', 'Agate', 'Sparta Transporter', 'Want to return to Sparta?'),
    ('Agate_006', 'Agate', 'Sparta Transporter', 'Want to return to Sparta?'),
    ('Agate_007', 'Agate', 'Athenian Quest Envoy', 'please choose a place suitable for you.'),
    ('Agate_008', 'Agate', 'Spartan Quest Envoy', 'please choose a place suitable for you.'),
    ('Agate_009', 'Agate', 'Pan''s Envoy', 'Pan sent me here to assist those brave warriors who wish to visit his labyrinth! Ask me for |cff39D8B8invitation part 1|cffffffff and I will give it to you. Only one request can be made every 24 hours.'),
    ('Agate_010', 'Agate', 'Pan''s Envoy', 'Pan sent me here to assist those brave warriors who wish to visit his labyrinth! Ask me for |cff39D8B8invitation part 1|cffffffff and I will give it to you. Only one request can be made every 24 hours.'),
    ('Agate_011', 'Agate', 'Athenian Quartermaster', 'The Treasure Land used to be beautiful. Where have all those monsters that have taken it over come from? Take my tuck nets to capture all of them.'),
    ('Agate_012', 'Agate', 'Spartan Quartermaster', 'The Treasure Land used to be beautiful. Where have all those monsters that have taken it over come from? Take my tuck nets to capture all of them.'),
    ('Agate2_001', 'Agate2', 'Athens Transporter', 'Want to return to Athens?'),
    ('Agate2_002', 'Agate2', 'Athens Transporter', 'Want to return to Athens?'),
    ('Agate2_003', 'Agate2', 'Athens Transporter', 'Want to return to Athens?'),
    ('Agate2_004', 'Agate2', 'Sparta Transporter', 'Want to return to Sparta?'),
    ('Agate2_005', 'Agate2', 'Sparta Transporter', 'Want to return to Sparta?'),
    ('Agate2_006', 'Agate2', 'Sparta Transporter', 'Want to return to Sparta?'),
    ('Agate2_007', 'Agate2', 'Athenian Quest Envoy', 'please choose a place suitable for you.'),
    ('Agate2_008', 'Agate2', 'Spartan Quest Envoy', 'please choose a place suitable for you.'),
    ('Agate2_009', 'Agate2', 'Pan''s Envoy', 'Pan sent me here to assist those brave warriors who wish to visit his labyrinth! Ask me for |cff39D8B8invitation part 1|cffffffff and I will give it to you. Only one request can be made every 24 hours.'),
    ('Agate2_010', 'Agate2', 'Pan''s Envoy', 'Pan sent me here to assist those brave warriors who wish to visit his labyrinth! Ask me for |cff39D8B8invitation part 1|cffffffff and I will give it to you. Only one request can be made every 24 hours.'),
    ('Alcatraz_Island_001', 'Alcatraz_Island', 'Correction Officer', 'I can''t remember how long I''ve been here, nor can I remember the number of criminals this place has housed over the years. You can leave this place early if you can pass my 3 tests, or else, you will serve your full term here with me. |cffF14187Note: You have to wait 5 minutes before you can have another try.|cffffffff'),
    ('Arena_001', 'Arena', 'Arena Vendor', 'I offer the best quality peanuts, fried sunflower seeds, beer, benches and more.'),
    ('Arena_002', 'Arena', 'Arena Doorkeeper', 'Take care anytime you venture outside. Do you need me to find you a doctor?'),
    ('Arena_003', 'Arena', 'Arena Gatekeeper', 'If you are not strong enough, you will very likely return from the outside on a stretcher.'),
    ('Arena_004', 'Arena', 'Arena Ward', 'Wow, another soldier survived!'),
    ('Arena_005', 'Arena', 'Physician', 'I am the best physician in Greece. What can I do for you?'),
    ('Argolis_All_001', 'Argolis_All', 'Menesthes', 'I must defend my country, why not come with me? Argolis and Argo Town are Sparta''s allies.'),
    ('Argolis_All_002', 'Argolis_All', 'Eurumedon', 'Oh, the oracle says: You are a good man.'),
    ('Argolis_All_003', 'Argolis_All', 'Menelaos', '...It''s hasn''t been safe recently. I hope the war will be over soon. I hope the Gods are watching over us on Olympus.'),
    ('Argolis_All_004', 'Argolis_All', 'Aeoliah', 'What a fine day! Why not go hunting outdoors?'),
    ('Argolis_All_005', 'Argolis_All', 'Agamemnon', 'I am the descendant of the Tantalus family… That is to say I have noble blood.'),
    ('Argolis_All_006', 'Argolis_All', 'Postman', 'I am a little tired, you can have a try… Maybe this job is not fit for me. Everyone says postmen are the best marathon athletes.'),
    ('Argolis_All_007', 'Argolis_All', '[Props]Iphigenia', 'Artemis will bless us. I will become her priest and provide offerings for her.'),
    ('Argolis_All_008', 'Argolis_All', 'Tydeus', 'Carving a boar head or other beasts on the shield can frightens enemies. But what if the enemies are of the same kind?'),
    ('Argolis_All_009', 'Argolis_All', 'Argo Volunteer', 'All members of the Argo Volunteer Club are great.'),
    ('Argolis_All_010', 'Argolis_All', 'Boatman', 'What ship haven''t I made?'),
    ('Argolis_All_011', 'Argolis_All', 'Mopsus', 'Jason invited me to travel at sea. Only I can talk with the deceased.'),
    ('Argolis_All_012', 'Argolis_All', 'Eumaeus', 'I am Odysseus''s herdsman. Did you see him? He is great, I will follow him forever.'),
    ('Argolis_All_013', 'Argolis_All', 'Ancient Relics 7', 'Exchange Sheepskin Scroll 7 for |cffF14187Lost Book Chapter 7|cffffffff.'),
    ('Argolis_All_014', 'Argolis_All', 'Spartan Physician', 'I am the best physician in Greece. What can I do for you?'),
    ('Argolis_All_015', 'Argolis_All', 'Spartan Apothecary', 'From 7:00pm through 9:00pm on Fridays, you can claim some deadly poisons from me and then turn it over to an Assassin with the mission of taking down the hostile Consul. You can even choose to do it yourself, which is more rewarding but more risky.     Assassin''s Location:                                              Megara (-83，-87)       Megara (152，-92)     Plataea(-139，60)   Consul''s Location:                                                 Megara (28，-104)'),
    ('Argolis_All_016', 'Argolis_All', 'Spartan Consul', 'Hey brave warrior, I am the Spartan Consul. What have you got to contribute?'),
    ('Argolis_All_017', 'Argolis_All', 'Athenian Assassin', 'You can submit poisons to me in an attempt to assassinate the hostile Consul.'),
    ('Argolis_All_018', 'Argolis_All', 'Athenian Assassin', 'You can submit poisons to me in an attempt to assassinate the hostile Consul.'),
    ('Athens_001', 'Athens', 'Meletiou', 'Improving the public order should be your top priority right now. Although Athena can protect us, she is not always free.'),
    ('Athens_002', 'Athens', 'Neocles', 'Hey,why are you here? I am the Captain, though it''s a junior military title in Athens, I love my job.'),
    ('Athens_003', 'Athens', 'Azanes', 'What can I do for you? I am patrolling. Recruits must adapte themselves to the team ASAP. Semele is the hero Cadmus''s daughter, so she has the manner of the Cadmus family.'),
    ('Athens_004', 'Athens', 'Bubassus', 'Do you want to taste my snacks? I am a chef. There are few people as skillful as me. I will make a lot of food for the sacrifice ceremomy every time.'),
    ('Athens_005', 'Athens', 'Hybla', 'What can I do for you? I am very busy now. I have too many clothing orders to deal with. I hope more tailors will come to Athens.'),
    ('Athens_006', 'Athens', 'Hesper', 'The world originates from a point, can you understand?.. Before Zeus, there was Cronus. Before |cffebed99Cronus|cffffffff was Uranus, well, who was before|cffebed99Uranus|cffffffff?'),
    ('Athens_007', 'Athens', 'Nausipahnes', 'I will be a great man like my teacher and give a stunning lecture to all citizens in the amphitheater.'),
    ('Athens_008', 'Athens', 'Polyclitus', 'Do you feel that art has no borders? In Greece, there are three kinds of columns: Doric,Ionic, Corinthian. I wish to be a sculptor in the future.'),
    ('Athens_009', 'Athens', 'Kreion', 'Athens is a free and democratic city.'),
    ('Athens_010', 'Athens', 'Jacinta', 'Hi, I haven''t seen you before… Do you want some wine? Wini Wine is very popular now.'),
    ('Athens_011', 'Athens', '[Priest]Saizeriya', 'The Olympian Gods have blessed you… All gods are relatives of |cffF14187Zeus|cffffffff, but they don''t get along very often.'),
    ('Athens_012', 'Athens', 'Thanksgiving Envoy', 'Happy Thanksgiving Day, my brave fighters! Could you bring me some turkey meat and Thanksgiving Gift Certificates? If you do, I will reward you handsomely. If you also bring me one Thanksgiving Greetings Card, you will get even more rewards. Go ahead, there are a lot of turkeys just waiting for you to chase them in the Marathon_All.'),
    ('Athens_013', 'Athens', 'Adeimantus', 'Have you ever found treasures? If you know some clues, please tell me! I am an archaeologist. Ancient kings liked to bury  treasures in their tombs.'),
    ('Athens_014', 'Athens', 'Ariston', 'Er, haven''t I seen you before? You are a newcomer, right?...'),
    ('Athens_015', 'Athens', 'Medea', 'Don''t touch me. Jason won''t know I am here. I will go back later.'),
    ('Athens_016', 'Athens', 'Theseus', 'When you decide to go to a labyrinth, you should prepare enough string so that you can use it to make a trail. Once I went on an expedition to Knossos in Crete this way. There were Minos and Minotaur living there.'),
    ('Athens_017', 'Athens', 'Europa', 'Which god do you like? Have you seen Satyr Gens? They are all attendants of Pan.'),
    ('Athens_018', 'Athens', 'Postman', 'Doing the legwork is interesting, but I must be exhausted after running every day.Have a good rest… You, too… I will pray for Hermes''s blessing to let me have a pair of wings.'),
    ('Athens_019', 'Athens', 'Paris', 'Athens is a good place. So is Sparta to the southwest of Athens. But they are engaged in war now.'),
    ('Athens_020', 'Athens', '[Sage]Gideon', 'A warrior must have strong body as well as excellent wisdom, what''s more, never give up!'),
    ('Athens_021', 'Athens', '[Props]Anemone', 'You should take enough potion to sustain your strength. I have many kinds to choose from.'),
    ('Athens_022', 'Athens', '[Jewelry]Circe', 'If you meet the Siren, remember to cover you ears or else you will be enchanted.'),
    ('Athens_023', 'Athens', '[Armor]Alastor', 'Hello. I have various |cffF14187armor|cffffffff. They can improve your defense, don''t miss out!'),
    ('Athens_024', 'Athens', 'Wanted Quest Issuer', 'If you''ve reached Level 50 and you wish to take on a wanted quest, come see me before 9:00pm. I can help you by issuing up to 5 wanted quests each day. Once the wanted quest you''ve taken on has been completed and turned in to the Wanted Quest Assesor, you will be rewarded. You can also help with wanted quests others have taken on, but you can only complete 5 wanted quests at most on any single day.'),
    ('Athens_025', 'Athens', '[Warehouse]Kyriakou', 'After the logistics are developed, I will suggest they form a |cffF14187Federal Trade Bank|cffffffff. Thus,the |cffF14187Atticas Alliance in Athens will become stronger.'),
    ('Athens_026', 'Athens', '[Warrior]Demetrius', 'Hi, what |cffF14187weapon|cffffffff do you need?'),
    ('Athens_027', 'Athens', '[Scholar]Renee', 'Even if you are a scholar, you should carry several weapons!'),
    ('Athens_028', 'Athens', '[Jewelry]Artisan', 'To forge |cffF14187Metal containers|cffffffff you must use a high temperature. You can master it after learning for a period. But processing and enchasing |cffF14187gems|cffffffff requires skills and patience. Not everyone can do it.'),
    ('Athens_029', 'Athens', '[Armor]Cobbler', 'Three cobblers equal a rich man. A |cffF14187Fable |cffffffff says, the rich will get used to the cobbler''s smell after staying together.'),
    ('Athens_030', 'Athens', '[Guild] Instance Supervisor', 'The Guild instance is currently not active.'),
    ('Athens_031', 'Athens', 'Oriental Cuisine Master', '|cffF14187Welcome, to our Mooncake Exchange this Mid-Autumn Festival!|cFFFFFFFF                Hail, my friend! I come a long way from the East, and I must say I have definite interest in Greek cuisine! Do you happen to have a Greek Cuisine Recipe with you? If not, I know a few ways you could get one! 1) At 2:00AM, 6:00AM, 10:00AM, 2:00PM, 6:00PM and 10:00PM daily, the Artemis Treasure Chest Leader will appear in the wilds - defeat him to get one!  2) Exchange Delicate Mooncakes with the Lunar Priest, and you might get one too!             If you already have a Greek Cuisine Recipe, you can exchange it with me for a Delicate Mooncake quest scroll!'),
    ('Athens_032', 'Athens', 'Lunar Priest', '|cffF14187 Welcome to the Mid-Autumn wish-making event! |cFFFFFFFFI heard an Oriental Cuisine Master is in town, and he is an expert at making delicate mooncakes as offerings to Artemis, the goddess of the moon. Can you bring me back some of these delicious mooncakes? I promise rich rewards for your effort.|cFFF79709 Rewards: |cFFFFFFFFCharacter Exp, Pet Exp, Character TP, Energy Zodiac.|cFFF79709 Starts: |cFFFFFFFFToday|cFFF79709Ends: |cFFFFFFFFPlease stay tuned for upcoming announcements on our official website.'),
    ('Athens_033', 'Athens', 'Pindus Master', 'During 11:00am to 11:45am Wed. and Sun. 9:00pm to 9:45pm Sat,the transporter beside me can send you to the Pindus Mountain Battlefield.'),
    ('Athens_034', 'Athens', 'Wanted Quest Assessor', 'Do you need my help to turn in a completed wanted quest? Once you''ve completed one wanted quest, I will reward you with one medal, which can be exchanged with the Wanted Warrant Issuer beside me for a variety of cool items.'),
    ('Athens_035', 'Athens', 'Santa Claus', 'Ho ho ho! The season of giving is here! Have you been good this year? Bring me some holiday cheer, and I might have a special gift waiting just for you.'),
    ('Athens_036', 'Athens', '[Skill]Simonides', 'Hi, people like to call me Simon. I want to create a tactical training school.'),
    ('Athens_037', 'Athens', '[Props]Vendor', 'The logistical distribution of Atticas is in the control of the Athens Noble Council, even the king cannot be involved in it.'),
    ('Athens_038', 'Athens', '[Guild] Quest Supervisor', 'All Guild members must help build up the Guild. Do this by completing any of my quests, and we will keep your contributions in mind.'),
    ('Athens_039', 'Athens', '[Daily Quest]Main City Issuer', 'Hi, please pray to Athena every week so that you will get her blessing.'),
    ('Athens_040', 'Athens', '[Polis Quest]Issuer', 'Warriors, are you ready? Fight for Athens.'),
    ('Athens_041', 'Athens', 'Transporter', 'I can send you to a remote place, but I suggest you reach a certain level before going there.'),
    ('Athens_042', 'Athens', 'Narcissus', 'My reflection is more beautiful than myself. I love my reflection. My heart is broken when the water wave ripples.'),
    ('Athens_043', 'Athens', 'Senator', 'Hey, boy, why do you point at me? Do you want to join the council? You need more training.'),
    ('Athens_044', 'Athens', 'Class Shifter', 'In Greece, you can choose to be a Warrior, Champion, Mage or Priest. Each of these classes have their own strong points.   If you are Level 100 or below, I am willing to shift your class to another and also shift your equipped items into items specific to the new class for free. If you are above Level 100, you should hand me 1 |cff39D8B8Class Shift Permit|cffffffff, otherwise I won''t help you to shift your class.'),
    ('Athens_045', 'Athens', 'Citizen', 'Collect sunflowers, sell them and make a living… Don''t disturb me…'),
    ('Athens_046', 'Athens', 'Actress', 'I want to found a choir.'),
    ('Athens_047', 'Athens', 'Traveler', 'It is said there is a three headed dog guarding the way to Hades. Its name is Cerberus.'),
    ('Athens_048', 'Athens', 'Retired Soldier', 'I have hunted lots of lions. It''s not so great! Hercules has a helmet made of lion fur.'),
    ('Athens_049', 'Athens', '[Guild] Guild Reg', 'Hey, traveler, I am Menetheus, the Athenian Guild Registrar. As long as you have reached level |cffF1418730|cffffffff and possess a "|cff39D8B8Guild Stone|cffffffff", I will approve the founding of your guild so that numerous Greek fighters will gather around you. If a guild lord is offline for |cffF1418715|cffffffff consecutive days, any guild member can apply to |cffF14187dismiss the lord|cffffffff. After the application is successful, a new guild lord will be elected according to members'' position and Gold contribution.'),
    ('Athens_050', 'Athens', '[Guild]Alter Supervisor', 'Now I am in charge of communication between you and gods. Athena will bless all Athens warriors.'),
    ('Athens_051', 'Athens', '[Guild] Member Advisor', 'As a member of the guild, you are entitled to all the benefits of membership. Come here for weekly prayer to double your EXP and talent points.'),
    ('Athens_052', 'Athens', '[Exchange]Alcippe', 'I am Ares''s daughter and I live in the Acropolis near Athens. What do you want to exchange for?'),
    ('Athens_053', 'Athens', 'Halloween Envoy', 'Happy Halloween! Everybody will be able to get a beautiful Halloween suit from me on this day each year. I also have plenty of pumpkin candy to give away……Oh, where is it?……where''s my pumpkin candy?……The little candies played a trick on me! They have changed into devils and flown to the main city to cause trouble. Put on your Halloween suit and catch them using the mysteriously powerful Halloween wand. Catch them and I''ll reward you well.'),
    ('Athens_054', 'Athens', 'Retrieving Officer', 'To increase the efficiency of camp construction, I gather various kinds of resources from citizens on behalf of the country on a random basis. Just bring your resources to us if you need to exchange them. Satisfactory terms and conditions are guaranteed! The first phase of the |cff39D8B8Hermes Stone|cffffffff recycling program will conclude soon, and the second phase of the |cff39D8B8Life Essence|cffffffff and |cff39D8B8Crystal|cffffffff recycling program has officially begun. Remember, these programs don''t last long, so please make a quick move if you''d like to exchange your resources!'),
    ('Athens_055', 'Athens', 'Faction Crier', 'War is imminent! In order to tally the number of soldiers fit for duty, the general has asked me to distribute |cff39D8B8one Nameplate|cffffffff to each Athenian warrior |cffF14187every day|cffffffff from |cffF14187Monday|cffffffff to |cffF14187Saturday|cffffffff. The Nameplates can be exchanged for |cffF14187Talent Points|cffffffff and |cffF14187Exp|cffffffff. Come improve your fighting abilities in defense of our beloved Athens!'),
    ('Athens_056', 'Athens', 'Battlefield Transporter', 'Our war with the Spartans has raged for a generation – from the Pindus Mountain to the Lelantine Farm. Euboea have always been good friends with us, but now they are being attacked by our enemies. We cannot stand by idly. From |cffF14187 10:45pm and 11:30pm|cffffffff on Saturdays, you can enter the Lelantine Farm to teach those Spartans a lesson. Notes: |cffF14187 Claim your rewards for the fight before 11:55pm, or else you will forfeit them.|cffffffff'),
    ('Athens_057', 'Athens', '[Village Leader]Admes', 'You may be a stranger, but I am glad to help you nonetheless. By the way, if you see my friend, Pylades, please tell him to pay me a visit.'),
    ('Athens_057_a', '', '', 'You are an eligible Athenian warrior, so Athena will endow you with a Portal Scroll. However, your backpack is full, tidy it up first.'),
    ('Athens_057_b', '', '', 'You are an eligible Athenian warrior! Athena will now endow you with a portal scroll which can teach you how to go to Marathon instantly. In addition, I will giving you a [Riding] book which can teach how you riding skills.'),
    ('Athens_057_c', '', '', 'You don''t have enough training. Claim a Portal Scroll from me when you are Level 40.'),
    ('Athens_058', 'Athens', 'Cupid', 'I am Cupid, the god of love and beauty. If you wish to marry your sweetheart then you can get engaged to them here. Then you must go to get a Whelk Necklace for me from Pan''s Maze. Remember to apply to get married once you''ve got the necklace. I am not free every day, you know.                                             |cffF14187 Notes: It''s the man''s responsibility to submit the applications to get engaged, married or to commence the wedding ceremony.'),
    ('Athens_059', 'Athens', 'Wedding Priest', 'I am Cupid''s right hand man. Weddings should be exciting and fun. If you want to make a wedding go with a bang come don''t forget to bring some red packets and fireworks!'),
    ('Athens_060', 'Athens', 'Instance Caller', 'Come find me if you want to enter an instance! For a more challenging task, visit the Training Ground, but remember, you need to be at least level |cffF1418740|cffffffff to qualify.  For the ultimate adventure, join the Medusa Challenge, but you need to be at least level |cffF1418790|cffffffff to participate. It is a new instance which is located at sea. Great rewards, including Honor that can be exchanged for better items, await those with the courage to fight for them.'),
    ('Athens_061', 'Athens', 'Labyrinth Quest Envoy', 'Zeus'' lover has been kidnapped. Can you do the Thundergod a favor? I suppose Zeus can wait till you are |cffF14187level 50|cffffffff…'),
    ('Athens_062', 'Athens', 'Sicily Refugee', 'Sicily has gone to hell, damned Hades! In order to purify and rebuild Sicily, we must destroy the inhuman monsters there.'),
    ('Athens_063', 'Athens', '[Guild] Event Supervisor', 'Sorry,I''m busy.'),
    ('Athens_064', 'Athens', 'King of Newbies', 'During the Alpha Test, they bravely slaughtered monsters with the zeal of a veteran, while also fearlessly completing the most difficult quests. Truly the best of the best.                    |cffF3ac5efRanking: Level|cffffffff                                                   |cfffff334Athens|cffffffff:                                                             Talia                                                           Siphon                                                              Kaylor                                                         Anabolim                                                        Mikali                                                               Auxi                                                            Cupcake                                                         bKeios                                                          misutka                                                         Celestia                                                        |cfffff334Sparta|cffffffff:                                                              Agha                                                                 BladeX                                                              Doko                                                              Drag0nPa                                                             AnkleR                                                              Twix                                                                 Krayzie                                                             Loke                                                                Pale                                                             Eldin'),
    ('Athens_065', 'Athens', 'Exterminator', 'During the Alpha Test, they made it their priority to make GodsWar the best game it could be. They tirelessly catalogued the flaws that needed to be polished before GodsWar could be what it has grown into today.                                            |cfffff3341st Prize|cffffffff:                                                           Fenrir                                                               |cfffff3342nd Prize|cffffffff:                                                          Harry                                                                Dryburgh                                                             |cfffff3343rd Prize|cffffffff:                                                           Sneike                                                               Goddess                                                              Silver                                                               Rary                                                                 Odysseus                                                             Kekze                                                                Eldin                                                                Glory                                                                Chiyame                                                              Chaos                                                                |cfffff334Encouragement Prize|cffffffff:                                                Graith                                                               Rary                                                                 do_Ob                                                                Madness                                                             Tempo                                                               BubbleoO                                                          llion81                                                              Marigold                                                             Mordrek                                                              Allanon                                                              Faye                                                                 Adrastos                                                             Sherazou                                                            Ambrose'),
    ('Athens_066', 'Athens', 'King of Fighters', 'During the Alpha Test, they were the first to run into the fray and the last to stop swinging their sword. They faced monsters and rival factions with the same determination to win.    |cff3ac5efRanking:Reputation|cffffffff                                                   |cfffff334Athens|cffffffff:                                                              Mikali                                                               Siphon                                                               Adrastos                                                             Keios                                                                Fenrir                                                               |cfffff334Sparta|cffffffff:                                                              Leonidas                                                             Agha                                                                 LingChen                                                             BladeX                                                               Twix'),
    ('Athens_067', 'Athens', 'Forge Master', 'During the Alpha Test, they created excellent weapons throughout the whole Greece and became true forge masters.                 |cfffff3341st Prize|cffffffff:                                                           Agha                                                                 |cfffff3342nd Prize|cffffffff:                                                           Joan                                                                 Keitegg                                                              |cfffff3343rd Prize|cffffffff:                                                           siphon                                                               Naheb                                                                Iceman                                                               !DeMoN!                                                              Hime'),
    ('Athens_068', 'Athens', 'B-GOLD Shop', 'Hey, come here! I have a wide range of goods. If you pay me with |cffF14187Bound Gold|cffffffff, I will give you some rare things.'),
    ('Athens_069', 'Athens', 'Teaching Manager', 'More and more people enter this ancient world everyday, but I am afraid they may get lost. When you''ve reached |cffF14187Level 50|cffffffff, you can apply to be a master and teach the newbies what you know, besides, they will receive |cffF14187special rewards|cffffffff from the Gods. |cffF14187One master|cffffffff can have up to |cffF141876 apprentices|cffffffff who are |cffF14187below Level 50|cffffffff. If they form a team, the master will gain Masters Ethics with the improvement of apprentices.'),
    ('Athens_070', 'Athens', 'Gear Mentor', 'Hephaestus is my master. Although I am not as skilful as him, I look more handsome. Yeah, I can help you |cffF14187enhance your gear|cffffffff, but don''t tell my master.'),
    ('Athens_071', 'Athens', 'Title Expert', 'Hi, you can obtain |cffF14187your attribute|cffffffff and |cffF14187class titles|cffffffff from me! I will also |cffF14187reward you|cffffffff if you win some special titles!'),
    ('Athens_072', 'Athens', 'Event Transporter', 'Labyrinth       |cffF14187Anytime|cffffffff                     50-140     Everyday Treasure Land   |cffF1418710:00pm - 11:00pm|cffffffff          60-140         Sun      Cursed Zone               |cffF14187any time|cffffffff          55-140       Everyday  Sicily           |cffF1418710:00pm - 12:00pm|cffffffff          25-140       Fri;     Pan''s Labyrinth  |cffF1418712:00pm - 6:00pm|cffffffff          70-140      Weekends Trojan Expedition   |cffF141878:00pm - 9:00pm|cffffffff        50-140      Thur      Romance Island   |cffF141878:30pm - 9:00pm|cffffffff            70-140       Wed/Sat  You can also enter Sicily at any time with a Mystic Spell except Fridays.  Romance Island is accessible 4:30pm--5:00pm on Sundays'),
    ('Athens_073', 'Athens', 'Battlefield Awarder', 'Please claim the rewards between |cffF1418711：45am-11:55pm on Wednesdays|cffffffff and Sundays, and |cffF141879:45pm-11:55pm on Saturdays|cffffffff after the battlefield event ends.'),
    ('Athens_074', 'Athens', 'Wishing Pool', 'This is a Wishing Pool. It is said that it will grant player''s wishes.'),
    ('Athens_075', 'Athens', 'Fortune Teller', 'As an oracle in touch with the divine power of the Gods, I can change your zodiac and grant you extraordinary luck for one day. However, I must use my divine power so the lucky time will be limited.'),
    ('Athens_076', 'Athens', 'War Supplier 1', 'You can hand in any war materials to me, but I won''t pay much. However, you can send the war materials to |cffF14187War Supplier 2|cffffffff in the suburbs or |cffF14187War Supplier 3|cffffffff in Marathon and they may give you higher prices.'),
    ('Athens_077', 'Athens', 'Point Exchanger', 'If you have enough points, you can come find me and exchange for rewards that will help enhance your equipment.'),
    ('Athens_078', 'Athens', 'Fitness Trainer 6', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_079', 'Athens', 'Fitness Trainer 7', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_080', 'Athens', 'Fitness Trainer 8', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_081', 'Athens', 'Fitness Trainer 9', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_082', 'Athens', 'Fitness Trainer 10', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_083', 'Athens', 'Mysterious Elder', 'I am an old man. Don''t ask where I''m from or where I''ll go ''cuz I wouldn''t tell you even if I knew. I am here to retrieve the Lost Book, so I will be able to give you one |cff39D8B8Sheepskin Scroll 7|cFFFFFFFF everyday. You need to get the other scrolls from the Boogyman that respawns every 2 hrs in the surburbs. Beware their leaders, because they usually have a |cff39D8B8Sheepskin Scroll 7|cFFFFFFFF on them. Follow the instructions on the scroll to find the corresponding Lost Book Chapters. Once you have collected them, I can help you piece them together into a fullversion of the Lost Book, and with it, you can obtain great rewards at the Wishing Pool.'),
    ('Athens_084', 'Athens', 'Festival Envoy', 'I am the Festival Envoy, and during the festivities, players who reach Level 30 can come to me and claim a small gift. |cffF14187In addition, all players can come to me and claim EXP fun time every weekend.|cffffffff'),
    ('Athens_085', 'Athens', 'Master Vestment Forger', 'Don''t call me Master Vestment Forger. Or else, I will be ashamed because the craft to forge vestments was invented by Hephaestus, the god of fire and metal-working, but I have merely mastered superficial knowledge of the craft.'),
    ('Athens_086', 'Athens', 'Holy Stone Artisan', 'Hey, adventurer, have you ever heard the ana "The vestment that has not been improved by a holy stone is not a good vestment"? Errr, I''ve forgotten which celebrity first said that. Anyway, he is right. Why not improve your vestments with holy stones now?'),
    ('Athens_087', 'Athens', 'Bound Gold Vendor', 'I am selling good stuffs. Traveler, why not browse my goods? Just give me some |cffF14187 Bound Gold|cffffffff, I will give you some rare items in return. Don''t tell this secret to others, okay?'),
    ('Athens_088', 'Athens', 'Pet Manager', 'I am a mage from Temple of Artemis on Delos Island. I''m able to communicate with pets. Bring me a pet, and I can help you prepare a |cff39D8B8Soul Contract|cffffffff, which allows you to |cff39D8B8merge|cffffffff a pet with another to concentrate their power, or allows your pet to be |cff39D8B8reborn|cffffffff; both paths are designed to strengthrn your pet. If you can get |cff39D8B8Pixie''s Tear|cffffffff, I can reveal the pet''s hidden growth rate. If you have |cff39D8B8Seal Jade (empty)|cffffffff, I can seal your pet for trade if it hasn''t been |cffF14187bounded|cffffffff to you.'),
    ('Athens_089', 'Athens', 'Pet Merchant', 'Have you ever heard about the Sphinx? It''s an Egyptian pharaoh''s pet. Just browse my goods, I am able to make your pet even stronger than the Sphinx.'),
    ('Athens_090', 'Athens', 'Pan''s Envoy', 'Pan sent me here to assist those brave warriors who wish to visit his labyrinth! Give me all |cff39D8B86 invitation parts|cffffffff, and I will give you |cff39D8B8an invitation letter|cffffffff and |cff39D8B8a certificate|cffffffff that can be redeemed for a free gift!'),
    ('Athens_091', 'Athens', 'Cupid''s Shadow', 'I am Cupid''s shadow. I''m always on the opposite side of Cupid. For example, I''ve been really busy lately handling applications for broken engagements and divorces. Ha-ha nothing lasts for ever!'),
    ('Athens_092', 'Athens', 'Spring Festival Envoy', 'Happy Spring Festival! This year, Valentine''s Day will be during Spring Festival. Love and renewal are in the air, but some annoying |cffF14187Snow Demons|cffffffff have begun attacking Sparta! The nerve of these beast! They have already reached the suburbs of Sparta. We must prevent them from invading the city! Brave adventurers, go destroy the |cffF14187 Snow Demons|cffffffff. They will drop a lot of cool stuff when killed that you can then exchange with me for cool rewards.'),
    ('Athens_093', 'Athens', '[Round Quest]Main City Issuer', 'I give out the round quest.'),
    ('Athens_094', 'Athens', '[Newbie Guide]', 'Hello. You will benefit a lot from communicating with friends. Please left click on an NPC and choose a function from the user menu after clicking a player. You can click quest target to |cff3ac5efAuto-trace|cffffffff after accepting a quest. Is it easy?'),
    ('Athens_095', 'Athens', '[Props Merchant]Kuriakis', 'Haha, I have everything that you expect to find. Come and buy something!'),
    ('Athens_096', 'Athens', '[Warrior Supplier]Alexiou', 'Hi, warrior! I have all kinds of weapons for you to choose from.'),
    ('Athens_097', 'Athens', 'Nemodes', 'Forging gear is manual labor and inlaying is mental labor. If you are not careful, it will…|cffebed99Hephaestus|cffffffff is our Ironsmiths''s patron saint. Lots of legendary weapons were made by him.'),
    ('Athens_098', 'Athens', 'Ion', 'Hello. There is no special event in the village today. When your level increases, you can accept a quest from the person who has a "|cfffaa955question mark above their head|cffffffff".'),
    ('Athens_099', 'Athens', '[Skill Merchant]Thisbe', 'There are lots of |cfff26659monsters|cffffffff outside the newbie camp, trying to defeat them is the best training.'),
    ('Athens_100', 'Athens', '[Warehouse]Belen', 'Warehouses can be used to deposit items, do you want to do so? Epeius has made a horse with much wood and the horse became the symbol of the |cfffaa955Trojan Horse Club|cffffffff.'),
    ('Athens_101', 'Athens', 'Zander', 'How are you, my dear friend?'),
    ('Athens_102', 'Athens', '[Armor Merchant]Judaeus', 'Prepare enough materials before fighting against monsters, so you can win. Are you ready? I have a variety of armor, have a look!'),
    ('Athens_103', 'Athens', 'Alns', 'I am good at painting on pillars and walls.'),
    ('Athens_104', 'Athens', 'Dorotheou', 'It is very important for a warrior to sustain physical strength.'),
    ('Athens_105', 'Athens', 'Homer', 'You don''t fight alone. Have you ever heard of the |cfffaa955Trojan Horse Club|cffffffff? A tall |cfffdd3b9Trojan Horse|cffffffff.'),
    ('Athens_106', 'Athens', 'Acacia', 'I am a stranger, but I will give my helping hand if I am needed. If you see my old friend Pylades, please ask him to find me.'),
    ('Athens_107', 'Athens', '[Scholar Supplier]Moya', 'A wise scholar doesn''t compete with others in strength.'),
    ('Athens_108', 'Athens', '[Jewelry Merchant]Antigone', 'Tragedies are performed in the theater, I don''t want to be a tragic heroine, I love my brothers and sisters. Have you ever been to |cff3ac5efThebes|cffffffff?'),
    ('Athens_109', 'Athens', 'Apothecary', '|cffF14187I am an apothecary.|cffffffff                                                To exchange gems or crystals for exp potions, or transfer potions, come see me.'),
    ('Athens_110', 'Athens', 'Pet Master', 'I am sent by Hera to distribute pet eggs to people of this world. Once you have an egg, click on it to hatch your baby pet.'),
    ('Athens_111', 'Athens', 'Spring Merrymaker', 'In order to enjoy a peaceful Spring Festival, we must defeat the Lunar Beast. This is not too difficult, but it is not without dangers. To get started we must first lure it out. People say the best way to lure this monster out from the shadows is with Spring Festival Firecrackers. This is where you come in. I need some special goods for Spring Festival, and if you bring them to me I will reward you with Spring Festival Firecrackers. If you want to learn more about how to find the Lunar Beast, talk with the Lunar Beast Slayer beside me.'),
    ('Athens_112', 'Athens', 'Lunar Beast Slayer', 'Great, now''s my time to shine. First, get some Spring Festival Firecrackers from the Spring Merrymaker beside me. I will lure the Lunar Beast out when I''ve lit enough Spring Festival Firecrackers, then we can defeat it together. I''ll even reward you for bringing it down. Do you want a fantastic Flying Carpet or a cute snowman?'),
    ('Athens_113', 'Athens', '[Event]Zeus'' Loyal Believer', 'The Almighty Zeus rules over the Olympian Gods with wisdom and gives us strength. I am unable to give him anything in return, except my gratitude and loyal service. Would you like to do the same? Zeus will know of your devotion and give you blessings in return. Also, the more gifts you deliver, the greater the rewards - even double on the weekends! Just a hint, the |cffF14187 Cursed Zone |cffffffff and |cffF14187 Treasure Land |cffffffff have many of Zeus'' favorite gifts.'),
    ('Athens_114', 'Athens', '[Event]Praying Saint', 'Dear friend, you must always keep mind that without Zeus'' blessings we cannot live a good life at all. During every |cffF14187 0:00PM Saturday and 11:55PM Sunday|cffffffff, Zeus always commands me to give out innumerous precious treasures, including a great deal of experience and talent points. If you want to get them, you must first offer Zeus |cffF14187Praying Stone|cffffffff.'),
    ('Athens_115', 'Athens', 'Mid-autumn Gift Pack Giver', 'Provide a Mid-autumn Festival Gift Pack Dollar to me, and you will get a great gift pack containing Level 2 Crystal*50,  Greater Pixie Bag*1,  Level 3 Ruby*3, Level 3 Sapphire *3, Level 3 Emerald *3, Energy Holy Water*10, 10 of each a variety of Enduring Potion, Golden Iris*20, Super Healing Potion*99,  Super Mana Potion*99, Mysterious String Bag *10, Super Firework*5, Anima Potion*10 and pieces of a Magic Jade of the rare Blue Crystal Dragon.'),
    ('Athens_116', 'Athens', 'Mount Feeder', 'I am the best mount feeder in all of Greece. Just get your mount here in one piece, and I''ll take care of the rest.'),
    ('Athens_117', 'Athens', 'Easter Bunny Envoy', 'Come on! Get those naughty |cffF14187 Bunnies|cffffffff for me! The|cffF14187 Bunnies|cffffffff will spawn |cffF14187 Easter Eggs|cffffffff. Turn in the eggs to me for prizes. The prizes are available |cffF14187 1 hour |cffffffff after the|cffF14187 Bunny |cffffffff turns up. An extra |cffF14187 Weak Bunny|cffffffff will go to the player who turns in the largest number of Easter Eggs. The prizes must be claimed before the next round of |cffF14187 Bunnies|cffffffff spawn, or they will be forfeited. Only |cffF14187 Lvl 20+|cffffffff players are allowed participate in the Bunny busting event.'),
    ('Athens_118', 'Athens', 'Random Quest Manager', 'You will receive a Quest Sack from me to complete the Scroll Quest. After the quest is complete you will be rewarded with an Exp Pill and a chance at a Morning Dew. Each round includes 10 quests, the more quests you complete the more rewards you will receive. After completing the 10th quest, you will be rewarded with an extra Talent Stone 3.'),
    ('Athens_119', 'Athens', 'IGG Anniversary Envoy', 'Hey, I am the envoy for IGG''s special anniversary celebrations. Brave warrior, can you help me unlock the Treasure Chest? IGG has prepared big anniversary gifts！However, I dropped the key to the Treasure Chest by accident, and the key ended up several hundred pieces. I need you to retract some of  these pieces from Key Collector at Peloponnesus (73, -21)  or Marathon (81,63) . Be wary of the hostile Anniversary Chest Bandits who will assault whoever is holding a full set of pieces near the Anniversary Chest. Anniversary Chests need to be defended carefully, as those bandits are not pushovers.'),
    ('Athens_120', 'Athens', 'Profession Mentor', 'There are 4 types of Professions in GodsWar Online,|cffF14187Alchemy, Blacksmithing, Mythcrafting and Scholarship|cffffffff. If you are unhappy with your current profession, you may unlearn it and start a new one, but |cffF14187 this will completely remove all traces of the former profession,including any skills or recipes associated with it|cffffffff. Please make sure this is acceptable before you unlearn a profession.'),
    ('Athens_121', 'Athens', 'Alchemy Recipe Vendor', 'Hey, come take a look at my goods! Best in all of Greece!'),
    ('Athens_122', 'Athens', 'Ingredients Vendors', 'Look here! Good Ingredients for sale at reasonable price.'),
    ('Athens_123', 'Athens', 'Prize Chest', 'A convenient and thrilling chest where you claim the prizes (including B-GOLD) handed out by GM.'),
    ('Athens_124', 'Athens', 'Event Awarder', 'You can claim rewards from me after the event has closed.'),
    ('Athens_125', 'Athens', 'Trojan War Coordinator', 'Paris, the seductive prince of Troy, lured Helen away to the city of Troy.  Agamemnon, the great Greek leader has decided to launch an attack on Troy to get her back and teach the Trojans a lesson for their impudence.  All warriors in the land should join the fight for the glory of Greece!'),
    ('Athens_126', 'Athens', 'Carnival Envoy', 'A certain amount of wish-making credits is to be earned if you buy the selected items from the Item Mall before Sept 29th.      Before October 13th, you can use the earned wish-making credits to wish for the cool and rare items not available in the Item Mall. Your wish might come true with certain odds. Hesitate no further, and head over to win.'),
    ('Athens_127', 'Athens', 'Treasury Official', '|cffF14187I am responsible for the security of traders and merchants here.    |cffffffff The Treasure Bandits have been stealing from more and more people over the past several weeks, and we cannot let it continue. They must be brought to justice. This is why we are empowering anyone brave enough to face them with the task of capturing them.'),
    ('Athens_128', 'Athens', 'Easter Envoy', 'We’re introducing a fun new event in celebration of Easter! Click the Event Details button to find out more.'),
    ('Athens_129', 'Athens', 'Rich Man Envoy', 'I am the Rich Man Envoy. How about trying your luck here? Just hand over some Level 1 crystals to me for your chance to get rich quick!'),
    ('Athens_130', 'Athens', 'Sacred Sealer', '|cffF14187I am the Sacred Sealer:|cffffffff                                                                                                                  I have some scrolls that have legendary creatures sealed inside. With these scrolls, you can summon these beasts. Once they have been defeated, you can loot their treasure. Don''t think for a moment these scrolls are free, do you know what I had to do to get them...? Actually it''s better if I don''t tell you. At any rate, you''ve got to cough up some Gold if you want one of these scrolls.'),
    ('Athens_131', 'Athens', 'Holy Stone Redeemer', 'Everyone will be able to exchange up to 3 [Holy Stone Package Vouchers] with me for 3 bound [Holy Stone Packages]. One for one. [Holy Stone Package Vouchers] can be purchased from the [Item Mall] for only 1800 Gold. Each [Holy Stone Package Voucher] can be exchanged for one [Holy Stone Package] containing items worth up to 6,100 Gold.  If you have bought too many [Holy Stone Package Vouchers], you must return the unused ones for a refund . o learn how to use Holy Stones, check out our in-game tutorial here.[LINK to tutorial]'),
    ('Athens_132', 'Athens', 'Online Award Admin', 'Just stay online for 4 hours each day to receive one free Quest Scroll.'),
    ('Athens_133', 'Athens', 'B-Gold Trader', 'B-Gold Trader  Greetings! I''ve made a fortune trading B-Gold, and if you would like to take advantage of my services, I''ll give you 360 B-Gold in exchange for 180 Gold. Keep in mind I don''t carry a lot of B-Gold with me, after all one can''t be too careful these days, so I can only trade with each player once each day.Notes.    1.B-Gold binds when acquired. B-Gold can be used to purchase items from the [B-Gold vendor] and the [B-Gold shop] located in the area of (145,-137) in each of the main cities.2. Players can only exchange for B-Gold once each day.3. Players can only exchange for B-Gold between the hours of 12:00AM and 11:55PM each day.'),
    ('Athens_134', 'Athens', 'Warehouse Manager', 'With my help, you''ll be able to open a lot more Storagee Boxes using the same amount of Storage Box Keys.'),
    ('Athens_135', 'Athens', 'Forging Recipe Vendor', 'Hey, come take a look at my goods! Best in all of Greece!'),
    ('Athens_136', 'Athens', 'Mythcrafting Recipe Vendor', 'Hey, come take a look at my goods! Best in all of Greece!'),
    ('Athens_137', 'Athens', 'Scholarship Recipe Vendor', 'Hey, come take a look at my goods! Best in all of Greece!'),
    ('Athens_138', 'Athens', 'Plastic Surgeon', 'Do you want to change your gender? Don''t just stand there staring, if you''re not happy the way you are now, then tell me. Are you sure you want to change your gender?'),
    ('Athens_139', 'Athens', 'Personal Helper', 'I know how troublesome it is to only be able to use items one at a time - as such, I''ve devised a way to enable batch usage of |cff39D8B8[Morning Dew I], [EXP Stone 3], and [Talent Stone 3]|cffffffff! Well, you can thank me later!'),
    ('Athens_140', 'Athens', 'Mystery Merchant', 'Hail, adventurer! I''m from faraway, and I deal in all kinds of exotic and fine wares. Take a look!'),
    ('Athens_141', 'Athens', 'Faction Changer', 'Do you want to change your faction? Don’t just stand there in silence; if you’re not satisfied with your current faction, let me know. Are you certain you want to switch factions?'),
    ('Athens_142', 'Athens', 'Level Sealer', 'Ah, a bold adventurer! If you’ve reached the Level 89, would you like me to seal your level? Once sealed, you’ll remain at 89 but can still gain experience. This is useful for honing your skills and earning rewards without leveling up further. Think carefully—once sealed, you’ll be locked at this level until you choose to unseal. If you’re ready, let me know, and I’ll take care of the rest.'),
    ('Athens_143', 'Athens', 'Origin Enhancer', 'I may not be as skilled as Hephaestus, but I know how to make your gear shine. Whether it’s your mount or your wardrobe, I can enhance them to perfection. Just don''t expect my master to approve of my... extra flair."'),
    ('Athens_Newbie_001', 'Athens_Newbie', 'Farmer Yannis', 'Do you know how to tame an animal into a pet? Listen to me, it''s so easy, all you need is the right tool.'),
    ('Athens_Newbie_002', 'Athens_Newbie', 'Farmer Kiron', 'Oh, no, my farmland has been almost completely destroyed.'),
    ('Athens_Newbie_003', 'Athens_Newbie', 'Fisher Hamon', 'Please help me get back to the fishing village to help my people. It is currently being occupied by a horde of evil monsters.'),
    ('Athens_Newbie_004', 'Athens_Newbie', '[Skill]Jenna', 'When you hit a new level, you will be able to learn new spells from some items. You can loot these items from monsters or they can be purchased from the Mall. Once you''ve gained a new spell, remember to press the S key to unfold your spell panel and drag the spell into the action bar for quick use.'),
    ('Athens_Newbie_005', 'Athens_Newbie', 'Inspector Galen', 'I am busy inspecting everyone and everything. You wouldn''t believe how corrupt and evil everyone is. But I will continue to work hard to bring peace and justice to this beautiful land.'),
    ('Athens_Newbie_006', 'Athens_Newbie', 'Wanted Criminals', 'There are several tough criminals on the wanted list. Do you dare to attempt to capture any of them?'),
    ('Athens_Newbie_007', 'Athens_Newbie', '[Warehouse]Belen', 'Warehouses can be used to deposit items, do you want to do so? Epeius has made a horse with much wood and the horse became the symbol of the Trojan Horse Club.'),
    ('Athens_Newbie_008', 'Athens_Newbie', 'Zander', 'How are you, my dear friend?'),
    ('Athens_Newbie_009', 'Athens_Newbie', '[Armor]Judaeus', 'Prepare enough materials before fighting against monsters, so you can win. Are you ready? I have a variety of armor, have a look!'),
    ('Athens_Newbie_010', 'Athens_Newbie', 'Alns', 'I am good at painting on pillars and walls.'),
    ('Athens_Newbie_011', 'Athens_Newbie', 'Dorotheou', 'It is very important for a warrior to sustain physical strength.'),
    ('Athens_Newbie_012', 'Athens_Newbie', 'Homer', 'You don''t fight alone. Have you ever heard of the Trojan Horse Club? A tall Trojan Horse.'),
    ('Athens_Newbie_013', 'Athens_Newbie', 'Orestes', 'I am a stranger, but I will give my helping hand if I am needed. If you see my old friend Pylades, please ask him to find me.'),
    ('Athens_Newbie_014', 'Athens_Newbie', '[Scholar]Moya', 'A wise scholar doesn''t compete with others in strength.'),
    ('Athens_Newbie_015', 'Athens_Newbie', '[Jewelry]Antigone', 'Tragedies are performed in the theater, I don''t want to be a tragic heroine, I love my brothers and sisters. Have you ever been to Thebes?'),
    ('Athens_Newbie_016', 'Athens_Newbie', '[Props]Catherine', 'Sustaining physical strength is very important. What do you need. Trojans will not think there are Greek warriors inside the horse.'),
    ('Athens_Newbie_017', 'Athens_Newbie', 'Olympics Competitor', 'I plan to participate in the Sports Competition in Olympia. But Olympia belongs to Elis Polis now. The king of Elis wants to sign a peace treaty with Sparta during the competition. The torch relay is mysterious and superb…I excel in the marathon and archery.'),
    ('Athens_Newbie_018', 'Athens_Newbie', 'Newbie Events Transporter', 'If you are level |cffF141820-75|cffffffff, then I can send you to some |cffF1418special Newbie practicing maps|cffffffff between |cffF1418 8：00pmto9：00pm every day|cffffffff.'),
    ('Athens_Newbie_019', 'Athens_Newbie', 'Pet Master', 'I am sent by Hera to distribute pet eggs to people of this world. Once you have an egg, click on it to hatch your baby pet.'),
    ('Athens_Newbie_020', 'Athens_Newbie', 'Gear Giver', 'When you reach level |cffF1418710|cffffffff, come to me to claim some gear. You will be rewarded every |cffF141875|cffffffff levels from Level 10 to Level |cffF1418740|cffffffff.'),
    ('Athens_Newbie_021', 'Athens_Newbie', 'Gift Envoy', 'Ha-ha, happy holidays! I only appear on special holidays. Don''t miss out the gifts I am giving away!'),
    ('Athens_Newbie_022', 'Athens_Newbie', 'Instructor', 'Warrior, when you reach Level 3, 15 and 31, come talk with me and I will teach a bit more as well as give you rewards for working so hard.'),
    ('Athens_Newbie_023', 'Athens_Newbie', 'War Supplier 2', 'I won''t accept the materials until you give it to me while in a team with |cffF141875 people. Different materials will bring you different rewards.  Certainly, you can also hand in materials to |cffF14187War Supplier 1|cffffffff in the main city or |cffF14187War Supplier 3|cffffffff in Marathon.'),
    ('Athens_Newbie_024', 'Athens_Newbie', 'Fitness Trainer 1', 'Hello, I am Hygeia''s envoy. You are welcome to attend the round-the-city race |cffF1418712:00am-11:55pm, every Monday through Saturday|cFFFFFFFF. You are allowed to join the race up to |cffF14187 6 times |cffffffff a day! You will be rewarded 180 B-GOLD each the first two races in a day, and 90 B-GOLD for every race thereafter that day.'),
    ('Athens_Newbie_025', 'Athens_Newbie', 'Fitness Trainer 2', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_Newbie_026', 'Athens_Newbie', 'Fitness Trainer 3', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_Newbie_027', 'Athens_Newbie', 'Fitness Trainer 4', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_Newbie_028', 'Athens_Newbie', 'Fitness Trainer 5', 'Hello, I am Hygeia''s envoy. You are welcome to take part in the round-the-city race!'),
    ('Athens_Newbie_029', 'Athens_Newbie', 'Ancient Relics 1', 'Exchange |cff39D8B8Sheepskin Scroll 1|cffffffff for|cff39D8B8 Lost Book Chapter 1|cffffffff.'),
    ('Athens_Newbie_030', 'Athens_Newbie', 'Ancient Relics 6', 'Exchange |cff39D8B8Sheepskin Scroll 6|cffffffff for |cff39D8B8Lost Book Chapter 6|cffffffff.'),
    ('Athens_Newbie_031', 'Athens_Newbie', '[Event]Zeus'' Loyal Believer', 'The Almighty Zeus rules over the Olympian Gods with wisdom and gives us strength. I am unable to give him anything in return, except my gratitude and loyal service. Would you like to do the same? Zeus will know of your devotion and give you blessings in return. Also, the more gifts you deliver, the greater the rewards - even double on the weekends! Just a hint, the |cffF14187 Cursed Zone |cffffffff and |cffF14187 Treasure Land |cffffffff have many of Zeus'' favorite gifts.'),
    ('Athens_Newbie_032', 'Athens_Newbie', '[Event]Praying Saint', 'Dear friend, you must always keep mind that without Zeus'' blessings we cannot live a good life at all. During every |cffF14187 0:00PM Saturday and 11:55PM Sunday|cffffffff, Zeus always commands me to give out innumerous precious treasures, including a great deal of experience and talent points. If you want to get them, you must first offer Zeus |cffF14187Praying Stone|cffffffff.'),
    ('Athens_Newbie_033', 'Athens_Newbie', '-', 'Get inside the square to teleport.'),
    ('Atlantis_001', 'Atlantis', 'Callidora', 'Welcome! I speak for Poseidon and offer you this boon. You may find his presence deep within the tides of Atlantis, and through me, you may summon forth all that dwells within.'),
    ('Award', '', '', '|cffFFFF00claim|cffffffff'),
    ('BindingGold', '', '', '|cffFFFF00B_Gold|cffffffff'),
    ('Colosse10_001', 'Colosse10', 'Arena Groceror', 'I am selling various items for use in the arenas.'),
    ('Colosse10_002', 'Colosse10', 'Arena Physician', '|cffF14187I am a physician.|cffffffff    Simply pay me some B-Gold, and I will help regenerate your health and mana.'),
    ('Colosse10_003', 'Colosse10', 'Arena Score Admin', '|cffF14187I am the Arena Score Admin.|cffffffff     To see the score for each side, come see me.'),
    ('Colosse10_004', 'Colosse10', 'Area I Transporter', '|cffF14187I am the Area I Transporter.|cffffffff    Each arena is divided into 4 areas. To avoid a traffic jam, I suggest you enter the arena with the help of different transporters. To enter a certain area in an instant, turn to the specific transporter serving that area. I can teleport you to area I.'),
    ('Colosse10_005', 'Colosse10', 'Area II Transporter', '|cffF14187I am the Area II Transporter.|cffffffff    Each arena is divided into 4 areas. To avoid a traffic jam, I suggest you enter the arena with the help of different transporters. To enter a certain area in an instant, turn to the specific transporter serving that area. I can teleport you to area II.'),
