    ('WarField_020', 'WarField', '[Sparta]Fortune Altar', 'Obtain |cff39D8B8Holy Water|cffffffff from the War Supplier, and submit it here to amass points for later use. Each Spartan can exchange 1 Holy Water for 30 points, while each Athenian will earn 100 points.'),
    ('WarField_021', 'WarField', 'Battlemaster', 'Welcome to Pindus Mountains, home of an intense war. Can I help you, brave adventurer?'),
    ('WarField_022', 'WarField', 'Battlemaster', 'Welcome to Pindus Mountains, home of an intense war. Can I help you, brave adventurer?'),
    ('WarField_023', 'WarField', 'Athenian Physician', 'I am the best physician in Greece. What can I do for you?'),
    ('WarField_024', 'WarField', 'Spartan Physician', 'I am the best physician in Greece. What can I do for you?'),
    ('WarHall_001', 'WarHall', 'District A Transporter', '|cffF14187I am the District A Transporter.|cffffffff      I can send you to any of the arena''s, 1 - 5.'),
    ('WarHall_002', 'WarHall', 'District B Transporter', '|cffF14187I am the District B Transporter.|cffffffff      I can send you to any of the arena''s, 6 - 10.'),
