INSERT INTO npc_dialog_templates (script_key, function_name, dialog_index, sub_id, element_kind, text_key, text, stats)
VALUES
    ('newbie_guide', 'NpcFunNewMan_SetMsg', 1, 3, 'message', 'NF_L0_T5050', 'As a devoted follower of the Gods'', your job is to protect our homeland. Now I''m going to send you to the enemy''s area, please stay alert!', '{"SourceFile":"NpcFunNewMan.lua","Line":175,"Raw":"FirstWin_Text1:SetText(NF_L0_T5050);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetMsg', 1, 11, 'message', 'NF_L0_T5050', 'As a devoted follower of the Gods'', your job is to protect our homeland. Now I''m going to send you to the enemy''s area, please stay alert!', '{"SourceFile":"NpcFunNewMan.lua","Line":180,"Raw":"FirstWin_Text1:SetText(NF_L0_T5050);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetMsg', 1, 5000, 'message', 'NF_L0_T42', 'Greetings hero, I have a weapon for you. You can also forge such a weapon with gems. A good set of gear can improve your strength a lot.', '{"SourceFile":"NpcFunNewMan.lua","Line":170,"Raw":"FirstWin_Text1:SetText(NF_L0_T42);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetMsg', 1, 5001, 'message', 'NF_L0_FJ5040', 'Greetings hero, open your equipment column and click on the hammer at the bottom right to forge equipment. Now I will give you 1 Common Pisces Pendant, 1 Level 1 Sapphire and 25 Level 1 Crystals. Please forge them into an enhanced pendant. After that, I will reward you for the work.', '{"SourceFile":"NpcFunNewMan.lua","Line":185,"Raw":"FirstWin_Text1:SetText(NF_L0_FJ5040);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetMsg', 1, 5002, 'message', 'NF_L0_FJ5041', 'Good, now open your equipment column again and click on the hammer at the bottom right. This time I''m going to give you 1 Level 1 Emerald and 20 Level 1 Crystals. Please forge the Enhanced Pisces Pendant into a Grade 2 Pendant. Pay attention to the added attributes. After that, show it to me and I will reward you.', '{"SourceFile":"NpcFunNewMan.lua","Line":192,"Raw":"FirstWin_Text1:SetText(NF_L0_FJ5041);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetMsg', 1, 5003, 'message', 'NF_L0_FJ5042', 'Great, now open your equipment column one more time and click on the hammer at the bottom right to forge equipment. This time I will give you 1 Level 3 Ruby, please forge again and check out the changes in the gear. After that, show it to me and I will reward you.', '{"SourceFile":"NpcFunNewMan.lua","Line":199,"Raw":"FirstWin_Text1:SetText(NF_L0_FJ5042);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 3, 'button', 'NF_L0_5041', '|cffFFFF00*To Peloponnesus|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":43,"Raw":"Button:SetText(NF_L0_5041);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 11, 'button', 'NF_L0_111', '|cffFFFF00*To Marathon|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":37,"Raw":"Button:SetText(NF_L0_111);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5000, 'button', 'NF_L0_FJ5000', '|cffFFFF00Gear Effect|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":16,"Raw":"Button:SetText(NF_L0_FJ5000);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5001, 'button', 'NF_L0_FJ5001', '|cffFFFF00Gear Forging|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":21,"Raw":"Button:SetText(NF_L0_FJ5001);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5002, 'button', 'NF_L0_FJ5002', '|cffFFFF00Gear Forging|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":26,"Raw":"Button:SetText(NF_L0_FJ5002);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5003, 'button', 'NF_L0_FJ5003', '|cffFFFF00Gear Forging|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":31,"Raw":"Button:SetText(NF_L0_FJ5003);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5024, 'text', 'NF_L0_BD5024', 'You can accept this quest when you are bewteen Level |cff39D8B83-40.|cFFFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":47,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5024);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5029, 'text', 'NF_L0_BD5029', 'You have completed the three newbie guide quests.', '{"SourceFile":"NpcFunNewMan.lua","Line":52,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5029);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5030, 'text', 'NF_L0_BD5030', 'You have completed the first newbie guide quest. After you reach level |cff39D8B815|cFFFFFFFF, I will give you a new quest.', '{"SourceFile":"NpcFunNewMan.lua","Line":57,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5030);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5031, 'text', 'NF_L0_BD5031', 'You have completed the first two newbie guide quests, when you reach level |cff39D8B831|cFFFFFFFF, I will send you to the enemy''s area and let you see their ferocious appearance up close.', '{"SourceFile":"NpcFunNewMan.lua","Line":62,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5031);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 1, 5051, 'text', 'NF_L0_BD5051', 'Hi, my friend, please follow the instructions step by step then you will receive prizes.', '{"SourceFile":"NpcFunNewMan.lua","Line":67,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5051);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 1004, 'text', 'NF_L0_T1004', '|cffF14187Enter the forged gear in the box below|cffFFFFFF', '{"SourceFile":"NpcFunNewMan.lua","Line":96,"Raw":"FirstWin_Text1:SetText(NF_L0_T1004);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5005, 'text', 'NF_L0_BD5005', 'This is for you!', '{"SourceFile":"NpcFunNewMan.lua","Line":72,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5005);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5006, 'text', 'NF_L0_BD5006', 'You have finished this quest.', '{"SourceFile":"NpcFunNewMan.lua","Line":77,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5006);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5007, 'text', 'NF_L0_BD5007', 'Please keep enough space!', '{"SourceFile":"NpcFunNewMan.lua","Line":82,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5007);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5008, 'text', 'NF_L0_BD5008', 'You don''t meet the level requirement.', '{"SourceFile":"NpcFunNewMan.lua","Line":87,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5008);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5013, 'text', 'NF_L0_BD5013', '', '{"SourceFile":"NpcFunNewMan.lua","Line":92,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5013);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5015, 'button', 'NF_L0_BD5015', 'The first quest', '{"SourceFile":"NpcFunNewMan.lua","Line":107,"Raw":"Button:SetText(NF_L0_BD5015);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5016, 'button', 'NF_L0_BD5016', 'The second quest', '{"SourceFile":"NpcFunNewMan.lua","Line":113,"Raw":"Button:SetText(NF_L0_BD5016);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5017, 'button', 'NF_L0_BD5017', 'The third quest', '{"SourceFile":"NpcFunNewMan.lua","Line":119,"Raw":"Button:SetText(NF_L0_BD5017);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5020, 'text', 'NF_L0_BD5020', 'You have already done it.', '{"SourceFile":"NpcFunNewMan.lua","Line":123,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5020);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5021, 'text', 'NF_L0_BD5021', 'Not enough space', '{"SourceFile":"NpcFunNewMan.lua","Line":128,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5021);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5022, 'text', 'NF_L0_BD5022', 'Level is not high enough', '{"SourceFile":"NpcFunNewMan.lua","Line":133,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5022);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5023, 'text', 'NF_L0_BD5023', 'I''m going to give you some things to forge. Follow my instructions and when your done, show it to me. Then I will reward you.', '{"SourceFile":"NpcFunNewMan.lua","Line":138,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5023);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5025, 'text', 'NF_L0_BD5025', 'You are not qualified.', '{"SourceFile":"NpcFunNewMan.lua","Line":143,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5025);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5026, 'text', 'NF_L0_BD5026', 'Well done! Take your rewards, if you talk with me again, I will teach you more.', '{"SourceFile":"NpcFunNewMan.lua","Line":148,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5026);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5027, 'text', 'NF_L0_BD5027', 'Great! You have completed the three equipment forging quests. When you reach level 31, come back and I will send you to the enemy''s area to adventure.', '{"SourceFile":"NpcFunNewMan.lua","Line":153,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5027);"}'::jsonb),
    ('newbie_guide', 'NpcFunNewMan_SetText', 2, 5028, 'text', 'NF_L0_BD5028', 'Enter relevant things in the box', '{"SourceFile":"NpcFunNewMan.lua","Line":158,"Raw":"FirstWin_Text1:SetText(NF_L0_BD5028);"}'::jsonb)
