-- <auto-generated />
-- Generated from Godswar Origin NPC.INI, NpcName.dat, NPCDescription.dat, Quest.xml, NpcFun.lua, NpcFunNewMan.lua, and LuaText.lua.
CREATE TABLE IF NOT EXISTS npc_text_templates (
    npc_key varchar(96) PRIMARY KEY,
    scene_key varchar(64) NOT NULL DEFAULT '',
    display_name varchar(255) NOT NULL DEFAULT '',
    description text NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS ix_npc_text_templates_scene ON npc_text_templates (scene_key);

ON CONFLICT (npc_key) DO UPDATE
SET scene_key = EXCLUDED.scene_key,
    display_name = EXCLUDED.display_name,
    description = EXCLUDED.description;

CREATE TABLE IF NOT EXISTS npc_appearance_templates (
    template_key varchar(128) PRIMARY KEY,
    npc_key varchar(96) NOT NULL,
    scene_key varchar(64) NOT NULL DEFAULT '',
    internal_name varchar(255) NOT NULL DEFAULT '',
    sex smallint,
    stats jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS ix_npc_appearance_templates_npc_key ON npc_appearance_templates (npc_key);
CREATE INDEX IF NOT EXISTS ix_npc_appearance_templates_scene ON npc_appearance_templates (scene_key);

ON CONFLICT (template_key) DO UPDATE
SET npc_key = EXCLUDED.npc_key,
    scene_key = EXCLUDED.scene_key,
    internal_name = EXCLUDED.internal_name,
    sex = EXCLUDED.sex,
    stats = EXCLUDED.stats;

CREATE TABLE IF NOT EXISTS npc_spawn_references (
    quest_id integer NOT NULL,
    role varchar(16) NOT NULL,
    npc_key varchar(96) NOT NULL,
    map_id smallint NOT NULL,
    pos_x real NOT NULL,
    pos_z real NOT NULL,
    source varchar(64) NOT NULL DEFAULT '',
    PRIMARY KEY (quest_id, role, npc_key)
);

CREATE INDEX IF NOT EXISTS ix_npc_spawn_references_npc_key ON npc_spawn_references (npc_key);
CREATE INDEX IF NOT EXISTS ix_npc_spawn_references_map ON npc_spawn_references (map_id);

ON CONFLICT (quest_id, role, npc_key) DO UPDATE
SET map_id = EXCLUDED.map_id,
    pos_x = EXCLUDED.pos_x,
    pos_z = EXCLUDED.pos_z,
    source = EXCLUDED.source;

CREATE TABLE IF NOT EXISTS npc_function_templates (
    function_flag integer PRIMARY KEY,
    function_key varchar(64) NOT NULL UNIQUE,
    display_name varchar(255) NOT NULL DEFAULT '',
    script_file varchar(128) NOT NULL DEFAULT '',
    source varchar(64) NOT NULL DEFAULT ''
);

ON CONFLICT (function_flag) DO UPDATE
SET function_key = EXCLUDED.function_key,
    display_name = EXCLUDED.display_name,
    script_file = EXCLUDED.script_file,
    source = EXCLUDED.source;

CREATE TABLE IF NOT EXISTS npc_dialog_templates (
    script_key varchar(64) NOT NULL,
    function_name varchar(96) NOT NULL,
    dialog_index smallint NOT NULL,
    sub_id integer NOT NULL,
    element_kind varchar(32) NOT NULL,
    text_key varchar(64) NOT NULL,
    text text NOT NULL DEFAULT '',
    stats jsonb NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (script_key, function_name, dialog_index, sub_id, element_kind, text_key)
);

CREATE INDEX IF NOT EXISTS ix_npc_dialog_templates_script ON npc_dialog_templates (script_key, function_name);

ON CONFLICT (script_key, function_name, dialog_index, sub_id, element_kind, text_key) DO UPDATE
SET text = EXCLUDED.text,
    stats = EXCLUDED.stats;

CREATE OR REPLACE VIEW npc_template_summary AS
SELECT
    nt.npc_key,
    nt.scene_key,
    nt.display_name,
    nt.description,
    COUNT(DISTINCT na.template_key) AS appearance_count,
    COUNT(DISTINCT ns.quest_id) AS quest_reference_count
FROM npc_text_templates nt
LEFT JOIN npc_appearance_templates na ON na.npc_key = nt.npc_key
LEFT JOIN npc_spawn_references ns ON ns.npc_key = nt.npc_key
GROUP BY nt.npc_key, nt.scene_key, nt.display_name, nt.description;

CREATE OR REPLACE VIEW npc_guide_templates AS
SELECT *
FROM npc_template_summary
WHERE display_name ILIKE '%guide%'
   OR npc_key IN ('Athens_094', 'Sparta_094');
